def _env_int(name: str, default: int, lo: int = None, hi: int = None) -> int:
    """Parse an int env var without ever crashing the service on bad input."""
    try:
        val = int(os.environ.get(name, "") or default)
    except (TypeError, ValueError):
        val = default
    if lo is not None:
        val = max(lo, val)
    if hi is not None:
        val = min(hi, val)
    return val


