def get_router_db_path() -> str:
    """Return the active 9router sqlite DB path from candidates that actually exist."""
    for cand in ROUTER_DB_CANDIDATES:
        if cand and os.path.isfile(cand):
            return cand
    return "/root/.9router/db/data.sqlite"


