OPENCLAW_CONFIG_PATH = os.environ.get("OPENCLAW_CONFIG_PATH", "/root/.openclaw/openclaw.json")


def is_openclaw_control_ui_enabled() -> bool:
    try:
        if not os.path.isfile(OPENCLAW_CONFIG_PATH):
            return False
        with open(OPENCLAW_CONFIG_PATH, "r", encoding="utf-8") as f:
            cfg = json.load(f)
        return bool(cfg.get("gateway", {}).get("controlUi", {}).get("enabled", True))
    except Exception:
        return False


_openclaw_config_lock = threading.Lock()


def toggle_openclaw_control_ui() -> bool | None:
    """Toggle Control UI atomically; None means read/write failure."""
    tmp_path = None
    fd = -1
    with _openclaw_config_lock:
        try:
            if not os.path.isfile(OPENCLAW_CONFIG_PATH):
                return None
            with open(OPENCLAW_CONFIG_PATH, "r", encoding="utf-8") as f:
                cfg = json.load(f)
            if not isinstance(cfg, dict):
                return None
            gui = cfg.setdefault("gateway", {}).setdefault("controlUi", {})
            if not isinstance(gui, dict):
                return None
            new_val = not bool(gui.get("enabled", True))
            gui["enabled"] = new_val
            parent = os.path.dirname(os.path.abspath(OPENCLAW_CONFIG_PATH))
            fd, tmp_path = tempfile.mkstemp(dir=parent, prefix=".openclaw.json.tmp.")
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                fd = -1
                json.dump(cfg, f, indent=1)
                f.write("\n")
                f.flush()
                os.fsync(f.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, OPENCLAW_CONFIG_PATH)
            return new_val
        except (OSError, TypeError, ValueError):
            return None
        finally:
            if fd >= 0:
                with suppress(OSError):
                    os.close(fd)
            if tmp_path:
                with suppress(OSError):
                    os.unlink(tmp_path)


def _link_host() -> str:
    """Host untuk link absolut (IP LAN terdeteksi), bukan alamat hardcode.

    Panel dulu menulis `192.168.1.100` di href dasbor OpenClaw dan kartu Docker;
    begitu DHCP memberi alamat lain, middle-click/salin-link mengarah ke host yang
    salah. Nilai ini di-cache sebentar karena mendeteksi IP memanggil subprocess.
    """
    try:
        val = _ttl_cached("link_host_ip", 60.0, lambda: get_server_ips()[1] or "")
        if isinstance(val, str) and val:
            return val
    except Exception as e:
        _log_swallow("link host", e)
    return "127.0.0.1"


def _emmc_wear_upper(raw: int) -> int:
    """Batas atas bucket eMMC life_time (0x01 = 0-10%, 0x02 = 10-20%, ... 0x0A = 90-100%)."""
    return max(0, min(int(raw), 10)) * 10


def _emmc_wear_label(raw: int) -> str:
    """Label bucket aus eMMC sebagai rentang, sama seperti `mmc extcsd read` menjelaskannya."""
    raw = int(raw)
    if raw >= 0x0B:
        return ">100%"
    if raw <= 0:
        return "0%"
    return f"{(raw - 1) * 10}\u2013{min(raw, 10) * 10}%"


