_status_probe_cache = {}
_status_probe_cache_lock = threading.Lock()
_ttl_refreshing: set[str] = set()
_ttl_refreshing_lock = threading.Lock()
_ttl_inflight: dict[str, threading.Event] = {}
_ttl_generation: dict[str, int] = {}


def _ttl_cached(key: str, ttl: float, loader):
    """Return a short-lived cached probe result without holding the lock during I/O.
    Stale values refresh in background; cold misses coalesce concurrent callers."""
    now = time.monotonic()

    with _status_probe_cache_lock:
        entry = _status_probe_cache.get(key)

    if entry and (now - entry["at"] < ttl):
        return entry["value"]

    if entry:
        with _ttl_refreshing_lock:
            if key not in _ttl_refreshing:
                _ttl_refreshing.add(key)
                generation = _ttl_generation.get(key, 0)
                def _bg_worker():
                    try:
                        v = loader()
                        with _ttl_refreshing_lock:
                            if _ttl_generation.get(key, 0) == generation:
                                with _status_probe_cache_lock:
                                    _status_probe_cache[key] = {
                                        "at": time.monotonic(),
                                        "value": v,
                                    }
                    except Exception:
                        pass
                    finally:
                        with _ttl_refreshing_lock:
                            _ttl_refreshing.discard(key)
                threading.Thread(target=_bg_worker, daemon=True).start()
        return entry["value"]

    # Cold start: one caller loads synchronously; other callers wait briefly,
    # then use the value it published. Prevents request bursts from multiplying
    # expensive subprocess/SQLite probes after startup or invalidation.
    with _ttl_refreshing_lock:
        event = _ttl_inflight.get(key)
        if event is None:
            event = threading.Event()
            _ttl_inflight[key] = event
            generation = _ttl_generation.get(key, 0)
            owner = True
        else:
            generation = _ttl_generation.get(key, 0)
            owner = False
    if not owner:
        # Owner always signals in finally; invoking loader after a timeout
        # recreates the cold-start stampede this gate is meant to prevent.
        event.wait()
        with _status_probe_cache_lock:
            published = _status_probe_cache.get(key)
        if published:
            return published["value"]
        return None
    try:
        value = loader()
        with _ttl_refreshing_lock:
            current_generation = _ttl_generation.get(key, 0)
        if current_generation == generation:
            with _status_probe_cache_lock:
                _status_probe_cache[key] = {
                    "at": time.monotonic(),
                    "value": value,
                }
        return value
    finally:
        with _ttl_refreshing_lock:
            current = _ttl_inflight.pop(key, None)
            if current:
                current.set()


def _invalidate_status_cache(*keys: str) -> None:
    # Match refresh-worker lock order: generation first, cache second.
    # Do not clear _ttl_refreshing here; an old worker may still own its
    # marker, and clearing it lets a late finally block erase a new marker.
    with _ttl_refreshing_lock:
        if keys:
            for key in keys:
                _ttl_generation[key] = _ttl_generation.get(key, 0) + 1
        else:
            for key in set(_ttl_generation) | set(_ttl_refreshing):
                _ttl_generation[key] = _ttl_generation.get(key, 0) + 1
        with _status_probe_cache_lock:
            if keys:
                for key in keys:
                    _status_probe_cache.pop(key, None)
            else:
                _status_probe_cache.clear()

    if not keys or any(k in keys for k in ("processes_table", "gateway_info", "services", "system")):
        if "invalidate_service_cache" in globals():
            invalidate_service_cache(*keys)
        if "invalidate_docker_metric_cache" in globals():
            invalidate_docker_metric_cache(*keys)
        if "invalidate_systemctl_show_cache" in globals():
            invalidate_systemctl_show_cache(*keys)
        if "invalidate_router_port_cache" in globals():
            invalidate_router_port_cache()


def _probe_gateway_info() -> str:
    """Gateway service status: state, RSS memory, uptime."""
    try:
        r = subprocess.run(
            ["systemctl", "--user", "show", "hermes-gateway",
             "--property=ActiveState,MainPID,ActiveEnterTimestamp"],
            capture_output=True, text=True, timeout=SYSTEMCTL_TIMEOUT,
            env={**os.environ, "XDG_RUNTIME_DIR": "/run/user/0"},
        )
        if r.returncode != 0:
            return "?"
        props = {}
        for line in r.stdout.strip().split("\n"):
            if "=" in line:
                k, _, v = line.partition("=")
                props[k] = v
        pid = props.get("MainPID", "?")
        # Read RSS from /proc/<pid>/status instead of systemd MemoryCurrent
        # (which reports virtual memory, not physical)
        mem_mb = 0
        if pid and pid != "0":
            try:
                with open(f"/proc/{pid}/status") as f:
                    for line in f:
                        if line.startswith("VmRSS:"):
                            mem_mb = int(line.split()[1]) / 1024  # kB -> MB
                            break
            except Exception:
                pass
        # uptime from ActiveEnterTimestamp
        ts_str = props.get("ActiveEnterTimestamp", "")
        uptime_part = ""
        if ts_str:
            try:
                parts = ts_str.split()
                if len(parts) >= 3:
                    from datetime import datetime
                    dt_str = f"{parts[1]} {parts[2]}"
                    start = datetime.strptime(dt_str, "%Y-%m-%d %H:%M:%S")
                    delta = datetime.now() - start
                    d, rem = divmod(int(delta.total_seconds()), 86400)
                    hours, rem = divmod(rem, 3600)
                    mins, _ = divmod(rem, 60)
                    if d > 0:
                        uptime_part = f" · {d} hari {hours} jam"
                    else:
                        uptime_part = f" · {hours} jam {mins} mnt"
            except Exception:
                pass
        return f"PID {pid} · {mem_mb:.0f}MB{uptime_part}"
    except Exception:
        return "?"


def get_gateway_info() -> str:
    return _ttl_cached("gateway_info", 2.0, _probe_gateway_info)


