            f'      {status_badge}'
            f'    </div>'
            f'    <div style="font-size:0.72rem;color:var(--text-dim);margin:0.55rem 0 0.35rem 0;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:4px">'
            f'      <div>{port_label}</div>'
