def _probe_emmc_health() -> tuple[str, str]:
    """Check eMMC wear data from any mmcblk device that exposes eMMC sysfs fields."""
    readings = []

    for device_dir in glob.glob("/sys/block/mmcblk*/device"):
        try:
            with open(os.path.join(device_dir, "life_time")) as f:
                values = f.read().split()[:2]

            if len(values) < 2:
                continue

            raw = max(int(value, 16) for value in values)
            wear = _emmc_wear_upper(raw)

            with open(os.path.join(device_dir, "pre_eol_info")) as f:
                eol = int(f.read().strip(), 16)

            readings.append((wear, eol, raw))
        except (OSError, ValueError):
            continue

    if not readings:
        return "", "N/A"

    wear, eol, raw = max(readings, key=lambda item: (item[1], item[0]))

    cls = "down" if (wear >= 80 or eol == 3) else (
        "warn" if (wear >= 60 or eol == 2) else "up"
    )
    status = "Urgent" if eol == 3 else (
        "Warn" if eol == 2 else "Normal"
    )

    return cls, f"{_emmc_wear_label(raw)} aus ({status})"


def get_emmc_health() -> tuple[str, str]:
    return _ttl_cached(
        "emmc_health",
        60.0,
        _probe_emmc_health,
    )


def get_zram_info() -> str:
    """Read zram compression status."""
    try:
        with open("/sys/block/zram0/mm_stat") as f:
            orig, compr = [int(x) for x in f.read().split()[:2]]
        if orig == 0:
            return "0 MB"
        ratio = (orig / compr) if compr else 1.0
        return f"{orig // 1048576}MB ({ratio:.1f}x)"
    except Exception:
        return "–"


def get_cpu_temp() -> tuple[float, str]:
    """CPU temperature in °C from the thermal zone."""
    try:
        with open("/sys/class/thermal/thermal_zone0/temp") as f:
            millideg = int(f.read().strip())
        c = millideg / 1000.0
        return c, f"{c:.0f}°C"
    except Exception:
        return 0.0, "?"


def _probe_disk_stats() -> tuple[str, float]:
    """Scan real mounts once and return (display_text, highest_used_percent)."""
    skip_prefixes = ("/var/lib/docker", "/boot")
    skip_fstypes = {"tmpfs", "devtmpfs", "squashfs", "sysfs", "proc", "devpts"}
    parts = []
    worst = 0.0
    mounts = []
    try:
        with open("/proc/mounts") as f:
            for line in f:
                parts_line = line.split()
                if len(parts_line) < 3:
                    continue
                dev, mp, fstype = parts_line[:3]
                if fstype in skip_fstypes:
                    continue
                if any(mp.startswith(p) for p in skip_prefixes):
                    continue
                if "/rootfs/" in mp:  # docker overlay
                    continue
                if mp in [m[1] for m in mounts]:
                    continue  # duplicate mount point
                mounts.append((dev, mp, fstype))
    except Exception:
        return "?", 0.0

    # Assign labels: root = ROOT, others by device type
    for dev, mp, _ in mounts:
        try:
            st = os.statvfs(mp)
            total = st.f_blocks * st.f_frsize
            free = st.f_bavail * st.f_frsize
            if total == 0:
                continue
            used_pct = (total - free) / total * 100
            worst = max(worst, used_pct)
            total_gb = total / (1024 ** 3)
            used_gb = (total - free) / (1024 ** 3)
            if mp == "/":
                label = "ROOT"
            elif mp == "/DATA":
                label = "DATA"
            elif mp.startswith("/mnt/"):
                label = mp.split("/")[-1].upper()
            else:
                label = mp
            parts.append(f"{label} {used_pct:.0f}% ({used_gb:.1f}/{total_gb:.1f} GB)")
        except Exception:
            pass
    display_text = " · ".join(parts) if parts else "?"
    return display_text, worst


def _get_disk_stats() -> tuple[str, float]:
    return _ttl_cached("disk_stats", 10.0, _probe_disk_stats)


def get_disk_info() -> str:
    return _get_disk_stats()[0]


def get_disk_pct() -> float:
    return _get_disk_stats()[1]


def get_uptime() -> str:
    """Human-readable uptime from /proc/uptime (hari/jam/mnt)."""
    try:
        with open("/proc/uptime") as f:
            secs = float(f.read().split()[0])
        days, rem = divmod(int(secs), 86400)
        hours, rem = divmod(rem, 3600)
        minutes, _ = divmod(rem, 60)
        if days > 0:
            return f"{days} hari {hours} jam {minutes} mnt"
        return f"{hours} jam {minutes} mnt"
    except Exception:
        return "?"


def _probe_server_ips() -> tuple[str, str]:
    """Return (tailscale_ipv4, lan_ipv4). Empty string if not available."""
    ts_ip, lan_ip = "", ""
    try:
        r = subprocess.run(["tailscale", "ip", "-4"],
                           capture_output=True, text=True, timeout=INFO_TIMEOUT)
        if r.returncode == 0:
            ts_ip = r.stdout.strip().split("\n")[0]
    except Exception:
        pass
    try:
        r = subprocess.run(["hostname", "-I"],
                           capture_output=True, text=True, timeout=INFO_TIMEOUT)
        if r.returncode == 0:
            for ip in r.stdout.strip().split():
                if ip.startswith("192.168.") or ip.startswith("10.") or ip.startswith("172."):
                    lan_ip = ip
                    break
            if not lan_ip and r.stdout.strip():
                lan_ip = r.stdout.strip().split()[0]
    except Exception:
        pass
    return ts_ip, lan_ip


def get_server_ips() -> tuple[str, str]:
    return _ttl_cached(
        "server_ips",
        30.0,
        _probe_server_ips,
    )


_internet_status_cache = {"at": 0.0, "online": False, "ms": 0.0, "target": "1.1.1.1"}
_internet_status_lock = threading.Lock()
INTERNET_CACHE_TTL = 8.0  # seconds


def get_internet_status() -> tuple[bool, float, str]:
    """Check internet connectivity by reaching public DNS IPs (1.1.1.1 / 8.8.8.8) on port 53.
    Returns (is_online, latency_ms, target_host). Thread-safe with 8s TTL cache."""
    now = time.monotonic()
    with _internet_status_lock:
        if now - _internet_status_cache["at"] < INTERNET_CACHE_TTL:
            return (
                _internet_status_cache["online"],
                _internet_status_cache["ms"],
                _internet_status_cache.get("target", "1.1.1.1"),
            )

    online = False
    latency_ms = 0.0
    active_target = "1.1.1.1"
    for target in [("1.1.1.1", 53), ("8.8.8.8", 53)]:
        t0 = time.monotonic()
        try:
            with socket.create_connection(target, timeout=1.2) as s:
                pass
            latency_ms = (time.monotonic() - t0) * 1000
            online = True
            active_target = target[0]
            break
        except Exception:
            continue

    with _internet_status_lock:
        _internet_status_cache["at"] = now
        _internet_status_cache["online"] = online
        _internet_status_cache["ms"] = latency_ms
        _internet_status_cache["target"] = active_target

    return online, latency_ms, active_target


def get_rate_limited_providers() -> list[dict]:
    """Retrieve detailed recent errors for accounts/providers with actual account name."""
    details = []
    db_path = get_router_db_path()
    try:
        with closing(sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=INFO_TIMEOUT)) as conn:
            cur = conn.cursor()
            cur.execute("select id, provider, name, email, data from providerConnections")
            rows = cur.fetchall()
    except Exception:
        return details

    cutoff = datetime.now(timezone.utc) - timedelta(minutes=RATE_LIMIT_RECENCY_MINUTES)
    for cid, provider, col_name, col_email, data in rows:
        try:
            d = json.loads(data)
        except Exception:
            continue
        err = d.get("lastError")
        err_at = d.get("lastErrorAt")
        if not (err and err_at):
            continue
        try:
            ts = datetime.fromisoformat(err_at.replace("Z", "+00:00"))
        except Exception:
            continue
        if ts > cutoff:
            acc_name = col_name or col_email or d.get("name") or d.get("email") or cid[:8]
            # Convert to WIB (UTC+7, 24-hour format HH:MM:SS)
            wib_ts = ts + timedelta(hours=7)
            wib_str = wib_ts.strftime("%H:%M:%S")
            details.append({
                "id": cid[:8],
                "name": str(acc_name),
                "provider": provider,
                "error_at": wib_str,
                "error": str(err).strip()
            })
    return details


def set_panel_password(new_password: str, env_path: str = None) -> tuple[bool, str]:
    """Update or remove PANEL_PASSWORD in /etc/hermes-panel.env (mode 0600) and in-memory globals."""
    global PASSWORD, TOKEN, AUTH_SECRET, SESSION_VALUE
    if "\n" in new_password or "\r" in new_password:
        return False, "Password tidak boleh mengandung baris baru"
    new_password = new_password.strip()
    target_path = env_path or PANEL_ENV_PATH
    try:
        lines = []
        if os.path.exists(target_path):
            with open(target_path, "r", encoding="utf-8") as f:
                lines = f.read().splitlines()
        # Filter out existing PANEL_PASSWORD and legacy PANEL_TOKEN
        new_lines = [l for l in lines if not l.startswith(("PANEL_PASSWORD=", "PANEL_TOKEN="))]
        if new_password:
            new_lines.append("PANEL_PASSWORD=" + json.dumps(new_password, ensure_ascii=False))
        parent = os.path.dirname(os.path.abspath(target_path))
        os.makedirs(parent, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=parent, prefix=".hermes-panel.env.")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write("\n".join(new_lines) + ("\n" if new_lines else ""))
                f.flush()
                os.fsync(f.fileno())
            os.chmod(tmp, 0o600)
            os.replace(tmp, target_path)
        finally:
            if os.path.exists(tmp):
                try:
                    os.unlink(tmp)
                except OSError:
                    pass
    except Exception as exc:
        return False, f"Gagal menyimpan ke {target_path}: {exc}"

    PASSWORD = new_password
    if env_path is None:
        TOKEN = ""  # Clear legacy token to ensure passwordless mode is clean on live server
    AUTH_SECRET = PASSWORD or TOKEN
    SESSION_VALUE = (
        hmac.new(AUTH_SECRET.encode("utf-8"), b"hermes-panel-session", hashlib.sha256).hexdigest()
        if AUTH_SECRET
        else ""
    )
    msg = "Kata sandi panel berhasil diatur." if new_password else "Kata sandi panel berhasil dihapus (mode bebas tanpa login aktif)."
    return True, msg



# --- Sesi Hermes: jembatan read-only ke state.db (tab "Sesi") -----------------
# Hermes menyimpan seluruh percakapan di ~/.hermes/state.db (tabel sessions +
# messages + indeks FTS). Panel hanya MEMBACA (mode=ro), tidak pernah menulis.
HERMES_STATE_DB = os.environ.get("HERMES_STATE_DB", "/root/.hermes/state.db")
SESSIONS_PAGE_LIMIT = 25
SESSION_MSG_LIMIT = 40
SESSION_CONTENT_CHARS = 700


def _state_db_readonly():
    """Koneksi read-only ke state.db; None bila berkas tidak ada."""
    if not os.path.isfile(HERMES_STATE_DB):
        return None
    conn = sqlite3.connect(f"file:{HERMES_STATE_DB}?mode=ro", uri=True, timeout=3.0)
    conn.row_factory = sqlite3.Row
    return conn


def _session_meta(row) -> dict:
    started = float(row["started_at"] or 0)
    last = float(row["last_activity_at"] or started or 0)
    return {
        "id": row["id"],
        "title": redact_sensitive_tokens(str(row["title"] or "")).strip() or "(tanpa judul)",
        "source": str(row["source"] or ""),
        "profile": str(row["profile_name"] or ""),
        "model": str(row["model"] or ""),
        "messages": int(row["message_count"] or 0),
        "tool_calls": int(row["tool_call_count"] or 0),
        "input_tokens": int(row["input_tokens"] or 0),
        "output_tokens": int(row["output_tokens"] or 0),
        "cache_read_tokens": int(row["cache_read_tokens"] or 0),
        "cost_usd": round(float(row["estimated_cost_usd"] or 0.0), 6),
        "started_at": started,
        "last_activity_at": last,
        "age_seconds": max(0, int(time.time() - last)) if last else None,
        "active": row["ended_at"] is None,
        "parent_id": (row["parent_session_id"] or ""),
    }


def _clamp_limit(raw, default: int, ceiling: int) -> int:
    try:
        val = int(raw)
    except (TypeError, ValueError):
        return default
    return max(1, min(ceiling, val))


def list_hermes_sessions(limit: int = SESSIONS_PAGE_LIMIT, source: str = "", profile: str = "") -> dict:
    """Sesi terbaru (diurutkan aktivitas terakhir). Read-only, tanpa rahasia."""
    conn = _state_db_readonly()
    if conn is None:
        return {"ok": False, "error": f"state.db tidak ditemukan: {HERMES_STATE_DB}", "sessions": []}
    try:
        where = ["hidden = 0"]
        params: list = []
        if source:
            where.append("source = ?")
            params.append(source)
        if profile:
            where.append("profile_name = ?")
            params.append(profile)
        params.append(limit)
        rows = conn.execute(
            "SELECT id,title,source,profile_name,model,message_count,tool_call_count,"
            "input_tokens,output_tokens,cache_read_tokens,estimated_cost_usd,"
            "started_at,ended_at,last_activity_at,parent_session_id "
            f"FROM sessions WHERE {' AND '.join(where)} "
            "ORDER BY COALESCE(last_activity_at, started_at) DESC LIMIT ?",
            params,
        ).fetchall()
        total = conn.execute("SELECT COUNT(*) FROM sessions WHERE hidden = 0").fetchone()[0]
        facets = [
            {"source": r[0], "count": r[1]}
            for r in conn.execute(
                "SELECT source, COUNT(*) FROM sessions WHERE hidden = 0 "
                "GROUP BY source ORDER BY COUNT(*) DESC").fetchall()
        ]
        return {"ok": True, "sessions": [_session_meta(r) for r in rows],
                "total": int(total), "facets": facets}
    except sqlite3.Error as exc:
        return {"ok": False, "error": f"gagal membaca state.db: {exc}", "sessions": []}
    finally:
        conn.close()


def search_hermes_messages(query: str, limit: int = SESSIONS_PAGE_LIMIT) -> dict:
    """Cari isi percakapan (FTS5) dan kelompokkan per sesi."""
    q = (query or "").strip()
    if not q:
        return {"ok": False, "error": "Kata kunci pencarian kosong", "sessions": []}
    conn = _state_db_readonly()
    if conn is None:
        return {"ok": False, "error": f"state.db tidak ditemukan: {HERMES_STATE_DB}", "sessions": []}
    try:
        # Kutip tiap token agar karakter operator FTS tidak dianggap sintaks.
        tokens = [t for t in re.split(r"\s+", q) if t]
        fts_query = " ".join('"' + t.replace('"', "") + '"' for t in tokens)
        rows = conn.execute(
            "SELECT m.session_id, m.role, m.content, m.timestamp, "
            "       s.title, s.source, s.profile_name, s.model "
            "FROM messages_fts f "
            "JOIN messages m ON m.id = f.rowid "
            "JOIN sessions s ON s.id = m.session_id "
            "WHERE messages_fts MATCH ? AND s.hidden = 0 "
            "ORDER BY m.timestamp DESC LIMIT ?",
            (fts_query, limit * 3),
        ).fetchall()
        grouped: dict[str, dict] = {}
        for r in rows:
            sid = r["session_id"]
            entry = grouped.get(sid)
            if entry is None:
                if len(grouped) >= limit:
                    continue
                entry = {
                    "id": sid,
                    "title": redact_sensitive_tokens(str(r["title"] or "")).strip() or "(tanpa judul)",
                    "source": str(r["source"] or ""),
                    "profile": str(r["profile_name"] or ""),
                    "model": str(r["model"] or ""),
                    "hits": [],
                }
                grouped[sid] = entry
            if len(entry["hits"]) < 3:
                text = redact_sensitive_tokens(str(r["content"] or ""))
                entry["hits"].append({
                    "role": str(r["role"] or ""),
                    "snippet": _session_text(text, 220),
                    "timestamp": float(r["timestamp"] or 0),
                })
        return {"ok": True, "query": q, "sessions": list(grouped.values()),
                "matched_messages": len(rows)}
    except sqlite3.Error as exc:
        return {"ok": False, "error": f"pencarian gagal: {exc}", "sessions": []}
    finally:
        conn.close()


def _session_text(text: str, limit: int = SESSION_CONTENT_CHARS) -> str:
    """Rapikan isi pesan untuk ditampilkan (tanpa rahasia, dipotong di batas kata)."""
    text = redact_sensitive_tokens(str(text or "")).strip()
    if len(text) <= limit:
        return text
    cut = text[:limit]
    space = cut.rfind(" ")
    if space > limit * 0.6:
        cut = cut[:space]
    return cut + "…"


def get_hermes_session_detail(session_id: str, limit: int = SESSION_MSG_LIMIT) -> dict:
    """Metadata satu sesi + pesan terakhir (urut waktu naik)."""
    sid = (session_id or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_\-:.]+", sid or ""):
        return {"ok": False, "error": "ID sesi tidak valid", "messages": []}
    conn = _state_db_readonly()
    if conn is None:
        return {"ok": False, "error": f"state.db tidak ditemukan: {HERMES_STATE_DB}", "messages": []}
    try:
        row = conn.execute(
            "SELECT id,title,source,profile_name,model,message_count,tool_call_count,"
            "input_tokens,output_tokens,cache_read_tokens,estimated_cost_usd,"
            "started_at,ended_at,last_activity_at,parent_session_id "
            "FROM sessions WHERE id = ?", (sid,)).fetchone()
        if row is None:
            return {"ok": False, "error": "Sesi tidak ditemukan", "messages": []}
        msgs = conn.execute(
            "SELECT role, content, tool_name, timestamp, token_count FROM messages "
            "WHERE session_id = ? ORDER BY timestamp DESC LIMIT ?", (sid, limit)).fetchall()
        messages = []
        for m in reversed(msgs):
            messages.append({
                "role": str(m["role"] or ""),
                "tool_name": str(m["tool_name"] or ""),
                "text": _session_text(m["content"]),
                "timestamp": float(m["timestamp"] or 0),
                "tokens": int(m["token_count"] or 0),
            })
        meta = _session_meta(row)
        meta["shown_messages"] = len(messages)
        return {"ok": True, "session": meta, "messages": messages}
    except sqlite3.Error as exc:
        return {"ok": False, "error": f"gagal membaca sesi: {exc}", "messages": []}
    finally:
        conn.close()


