# ---------------------------------------------------------------------------
# Provider quota — per-account AI usage, sourced from 9router /api/usage/{id}
#
# 9router keeps one row per linked account in providerConnections and exposes
# GET /api/usage/{connectionId} (cookie auth). Shapes differ per provider, so
# everything is normalised here into one schema the frontend can render blindly.
# Read-only against the 9router DB; never writes to it.
# ---------------------------------------------------------------------------

QUOTA_CACHE_PATH = "/opt/AppData/hermes-native/hermes-data/cache/provider_quota.json"
QUOTA_TTL = 120.0            # seconds a snapshot is served without refetching
QUOTA_TIMEOUT = 8.0          # per-account HTTP timeout
QUOTA_MAX_WORKERS = 8

# Providers whose accounts are never polled for quota. Each poll hits the
# provider's own billing endpoint per account, and CodeBuddy treats repeated
# polling of many accounts from one IP as "unusual activity" — the same signal
# that got accounts restricted. Override with PANEL_QUOTA_SKIP_PROVIDERS
# (comma-separated, empty string re-enables everything).
QUOTA_SKIP_PROVIDERS = frozenset(
    part.strip().lower()
    for part in (os.environ.get("PANEL_QUOTA_SKIP_PROVIDERS", "codebuddy-intl") or "").split(",")
    if part.strip()
)

_quota_mem = {"at": 0.0, "data": None}
_quota_lock = threading.Lock()
_quota_refreshing = {"on": False}
_quota_disk_lock = threading.Lock()

_router_auth = {"cookie": None, "at": 0.0, "fail_at": 0.0}
_router_auth_lock = threading.Lock()
_router_login_lock = threading.Lock()
_ROUTER_AUTH_TTL = 1800.0
_ROUTER_LOGIN_BACKOFF = 30.0

QUOTA_PROVIDER_ORDER = (
    "antigravity", "gemini", "codebuddy-intl", "codex", "qoder", "openai-compatible",
)
QUOTA_PROVIDER_LABELS = {
    "antigravity": "Antigravity",
    "gemini": "Gemini",
    "codebuddy-intl": "CodeBuddy",
    "codex": "Codex",
    "qoder": "Qoder",
    "openai-compatible": "OpenAI Compatible",
}

# Buckets that summarise a whole subscription rather than one model.
_QUOTA_AGGREGATE_KEYS = frozenset({
    "gemini_weekly", "gemini_session", "claude_gpt_weekly", "claude_gpt_session",
    "monthly", "session", "weekly", "user", "organization",
})

# Antigravity renders as exactly these five rows, in this order, always.
# (group key, UI label, main bucket, detail prefixes, detail exclusions)
_GEMINI4_SPECIAL_KEYS = frozenset({"gemini-4-argon", "gemini-4-carbon", "gemini-4-hydrogen"})
_ANTIGRAVITY_GROUPS = (
    ("gemini_session", "Gemini Models", "gemini_session", ("gemini-",),
     ("gemini-4-argon-", "gemini-4-carbon-", "gemini-4-hydrogen-")),
    ("gemini_weekly", "Gemini Models (Weekly)", "gemini_weekly", (), ()),
    ("claude_gpt_session", "Claude and GPT models", "claude_gpt_session", ("claude-",), ()),
    ("claude_gpt_weekly", "Claude and GPT models (Weekly)", "claude_gpt_weekly", (), ()),
    ("gemini-4-argon", "Gemini 4 Argon", None, ("gemini-4-argon-",), ()),
    ("gemini-4-carbon", "Gemini 4 Carbon", None, ("gemini-4-carbon-",), ()),
    ("gemini-4-hydrogen", "Gemini 4 Hydrogen", None, ("gemini-4-hydrogen-",), ()),
)
_ANTIGRAVITY_AGGREGATE_SET = frozenset({"gemini_session", "gemini_weekly", "claude_gpt_session", "claude_gpt_weekly", "argon_weekly", "gemini_argon_weekly", "gemini_argon_session"})

# Worst-first ordering used when rolling group statuses up to the account.
_ACCOUNT_STATUS_RANK = {
    "ok": 0, "low": 1, "auth_expired": 2, "unsupported": 2, "no_access": 2,
    "error": 3, "exhausted": 4,
}


def _quota_pct(bucket) -> float | None:
    """Remaining percentage 0-100, or None when the bucket has no denominator."""
    if not isinstance(bucket, dict):
        return None
    if bucket.get("unlimited"):
        return None
    val = None
    rp = bucket.get("remainingPercentage")
    if isinstance(rp, (int, float)) and not isinstance(rp, bool):
        val = float(rp)
    else:
        rem = bucket.get("remaining")
        total = bucket.get("total")
        used = bucket.get("used")
        if isinstance(total, (int, float)) and not isinstance(total, bool) and total > 0:
            # Prefer an explicit remaining count; some providers only ship "used".
            if isinstance(rem, (int, float)) and not isinstance(rem, bool):
                val = float(rem) / float(total) * 100.0
            elif isinstance(used, (int, float)) and not isinstance(used, bool):
                val = (float(total) - float(used)) / float(total) * 100.0
        else:
            frac = bucket.get("remainingFraction")
            if isinstance(frac, (int, float)) and not isinstance(frac, bool):
                val = float(frac) * 100.0
    if val is None or val != val:  # NaN guard
        return None
    return round(max(0.0, min(100.0, val)), 1)


def _quota_bucket_entry(key: str, bucket) -> dict:
    bucket = bucket if isinstance(bucket, dict) else {}
    return {
        "key": key,
        "label": bucket.get("displayName") or key,
        "pct": _quota_pct(bucket),
        "used": bucket.get("used"),
        "total": bucket.get("total"),
        "resetAt": bucket.get("resetAt"),
        "aggregate": key.lower() in _QUOTA_AGGREGATE_KEYS,
    }


def _quota_status_from_pcts(pcts) -> str:
    vals = [p for p in pcts if p is not None]
    if not vals:
        return "ok"  # nothing measurable (unlimited / zero total) is not a failure
    if all(p <= 0 for p in vals):
        return "exhausted"
    if any(p < 20 for p in vals):
        return "low"
    return "ok"


def _collect_group_models(details: list) -> tuple[list, list]:
    """Collapse High/Low/Medium/XHigh tier buckets into unique model chips."""
    model_names = []
    seen = {}
    for d in details:
        base = d["key"]
        for ksuf in ("-xhigh", "-high", "-medium", "-low"):
            if base.endswith(ksuf):
                base = base[:-len(ksuf)]
                break
        label = d["label"] or d["key"]
        for lsuf in (" (XHigh)", " (High)", " (Medium)", " (Low)"):
            label = label.replace(lsuf, "")
        pct = d.get("pct")
        if base not in seen:
            seen[base] = {"label": label, "pct": pct}
            model_names.append(label)
        elif pct is not None:
            cur = seen[base]["pct"]
            if cur is None or pct < cur:
                seen[base]["pct"] = pct
    model_entries = [
        {"label": v["label"], "pct": v["pct"]}
        for v in sorted(seen.values(), key=lambda x: (x["pct"] is None, x["pct"] if x["pct"] is not None else 0))
    ]
    return model_names, model_entries


def _antigravity_groups(quotas: dict) -> list:
    """Fold the flat antigravity bucket map into the mandated rows (including Gemini 4 Carbon & Hydrogen)."""
    groups = []
    for gkey, glabel, main_key, prefixes, excludes in _ANTIGRAVITY_GROUPS:
        details = []
        if prefixes:
            for bkey in sorted(quotas):
                if bkey in _ANTIGRAVITY_AGGREGATE_SET:
                    continue
                if not bkey.startswith(prefixes):
                    continue
                if any(bkey.startswith(x) for x in excludes):
                    continue
                raw_b = quotas[bkey]
                if gkey in _GEMINI4_SPECIAL_KEYS and (
                    bkey.endswith("-disabled") or (isinstance(raw_b, dict) and raw_b.get("disabled"))
                ):
                    continue
                details.append(_quota_bucket_entry(bkey, raw_b))

        if gkey in _GEMINI4_SPECIAL_KEYS:
            argon_agg = (quotas.get("argon_weekly") or quotas.get("gemini_argon_weekly")) if gkey == "gemini-4-argon" else None
            argon_agg = argon_agg if isinstance(argon_agg, dict) else None
            if not details and not argon_agg:
                note = "Tidak tersedia (butuh Pro/Ultra)" if gkey == "gemini-4-argon" else "Tidak tersedia di akun ini"
                groups.append({
                    "key": gkey, "label": glabel, "pct": None, "status": "no_access",
                    "resetAt": None, "fallback": False, "buckets": [],
                    "note": note, "model_names": [], "model_entries": [],
                })
                continue
            pcts = [d["pct"] for d in details if d["pct"] is not None]
            agg_pct = _quota_pct(argon_agg) if argon_agg else None
            if not pcts and agg_pct is not None:
                pcts = [agg_pct]
            worst = min(details, key=lambda d: (d["pct"] is None, d["pct"] or 0)) if details else argon_agg
            m_names, m_entries = _collect_group_models(details) if details else (["Gemini 4 Argon"], [{"label": "Gemini 4 Argon", "pct": agg_pct}])
            reset_at = (details[0]["resetAt"] if details and details[0].get("resetAt") else (argon_agg.get("resetAt") if argon_agg else None))
            groups.append({
                "key": gkey, "label": glabel,
                "pct": round(min(pcts), 1) if pcts else None,
                "status": _quota_status_from_pcts(pcts),
                "resetAt": reset_at,
                "used": worst.get("used"), "total": worst.get("total"),
                "fallback": False, "buckets": details, "note": None,
                "model_names": m_names, "model_entries": m_entries,
            })
            continue

        main = quotas.get(main_key) if main_key else None
        fallback = False
        used = total = None
        if isinstance(main, dict):
            pct = _quota_pct(main)
            reset = main.get("resetAt")
            used, total = main.get("used"), main.get("total")
        else:
            # Older accounts have no aggregate bucket: derive from the models.
            pcts = [d["pct"] for d in details if d["pct"] is not None]
            pct = round(min(pcts), 1) if pcts else None
            reset = details[0]["resetAt"] if details else None
            if details:
                worst = min(details, key=lambda d: (d["pct"] is None, d["pct"] or 0))
                used, total = worst.get("used"), worst.get("total")
            fallback = True

        m_names, m_entries = _collect_group_models(details) if details else ([], [])
        groups.append({
            "key": gkey, "label": glabel, "pct": pct,
            "status": _quota_status_from_pcts([pct] + [d["pct"] for d in details]),
            "resetAt": reset, "used": used, "total": total,
            "fallback": fallback, "buckets": details, "note": None,
            "model_names": m_names,
            "model_entries": m_entries,
        })
    return groups


def _normalize_quota_account(conn: dict, usage) -> dict:
    """One account row in the panel schema, whatever the provider's raw shape."""
    provider = conn.get("provider") or ""
    usage = usage if isinstance(usage, dict) else None
    quotas = (usage or {}).get("quotas") or {}
    quotas = quotas if isinstance(quotas, dict) else {}
    msg = str((usage or {}).get("message") or "")
    tier = (((usage or {}).get("subscriptionInfo") or {}).get("currentTier") or {}).get("id")

    acct = {
        "id": conn.get("id"),
        "provider": provider,
        "name": conn.get("name") or conn.get("email") or conn.get("id"),
        "email": conn.get("email") or "",
        "isActive": bool(conn.get("isActive")),
        "priority": conn.get("priority"),
        "plan": (usage or {}).get("plan") or "",
        "tier": tier,
        "status": "ok",
        "groups": [],
        "buckets": [],
        "note": None,
    }

    if usage is None:
        acct["status"] = "error"
        acct["note"] = "9router tidak merespons"
        return acct
    if "authentication expired" in msg.lower():
        acct["status"] = "auth_expired"
        acct["note"] = msg
        return acct
    if not quotas:
        acct["status"] = "unsupported"
        acct["note"] = msg or "Kuota tidak tersedia untuk koneksi ini"
        return acct

    if provider == "antigravity":
        groups = _antigravity_groups(quotas)
        acct["groups"] = groups
        worst = "ok"
        for g in groups:
            # A missing Argon/Carbon/Hydrogen allowance says nothing about the rest of the account.
            if g["key"] == "gemini-4-argon":
                continue
            if g["key"] in _GEMINI4_SPECIAL_KEYS and g["status"] == "no_access":
                continue
            if _ACCOUNT_STATUS_RANK.get(g["status"], 0) > _ACCOUNT_STATUS_RANK.get(worst, 0):
                worst = g["status"]
        acct["status"] = worst
    else:
        entries = [_quota_bucket_entry(k, v) for k, v in sorted(quotas.items())]
        acct["buckets"] = entries
        acct["status"] = _quota_status_from_pcts([e["pct"] for e in entries])
    return acct


def _router_password() -> str:
    """9router dashboard password: env first, then the systemd unit file."""
    for var in ("ROUTER_PASSWORD", "INITIAL_PASSWORD"):
        pw = os.environ.get(var)
        if pw:
            return pw
    try:
        with open("/etc/systemd/system/9router.service", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line.startswith("Environment=") and "INITIAL_PASSWORD=" in line:
                    raw = line.split("INITIAL_PASSWORD=", 1)[1].strip()
                    return raw.strip('"').strip("'")
    except OSError:
        pass
    return ""


def _router_cli_token() -> str:
    """Derive local 9router CLI bypass token (sha256 of machine-id + salt + cli-secret)."""
    for base in ("/root/.9router", os.path.expanduser("~/.9router")):
        mid_file = os.path.join(base, "machine-id")
        sec_file = os.path.join(base, "auth", "cli-secret")
        if os.path.isfile(mid_file) and os.path.isfile(sec_file):
            try:
                with open(mid_file, encoding="utf-8") as f1, open(sec_file, encoding="utf-8") as f2:
                    mid = f1.read().strip()
                    sec = f2.read().strip()
                    if mid and sec:
                        return hashlib.sha256((mid + "9r-cli-auth" + sec).encode("utf-8")).hexdigest()[:16]
            except Exception:
                pass
    return ""


def _router_origin() -> str:
    return f"http://127.0.0.1:{get_9router_port()}"


def _router_login(force: bool = False):
    """Return a usable 9router auth cookie, logging in at most once per backoff.

    The cookie is cached for _ROUTER_AUTH_TTL; a failed attempt parks logins for
    _ROUTER_LOGIN_BACKOFF so a burst of 401s cannot trip 9router's lockout.
    """
    now = time.monotonic()
    with _router_auth_lock:
        cookie = _router_auth["cookie"]
        if cookie and not force and (now - _router_auth["at"]) < _ROUTER_AUTH_TTL:
            return cookie
        if (now - _router_auth["fail_at"]) < _ROUTER_LOGIN_BACKOFF:
            return cookie
    with _router_login_lock:
        now = time.monotonic()
        with _router_auth_lock:
            cookie = _router_auth["cookie"]
            if cookie and not force and (now - _router_auth["at"]) < _ROUTER_AUTH_TTL:
                return cookie
            if (now - _router_auth["fail_at"]) < _ROUTER_LOGIN_BACKOFF:
                return cookie
        password = _router_password()
        if not password:
            with _router_auth_lock:
                _router_auth["fail_at"] = now
            return None
        try:
            req = urllib.request.Request(
                _router_origin() + "/api/auth/login",
                data=json.dumps({"password": password}).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with urllib.request.urlopen(req, timeout=QUOTA_TIMEOUT) as resp:
                headers = resp.headers.get_all("Set-Cookie") or []
            for item in headers:
                if item.startswith("auth_token="):
                    token = item.split(";", 1)[0]
                    with _router_auth_lock:
                        _router_auth["cookie"] = token
                        _router_auth["at"] = time.monotonic()
                        _router_auth["fail_at"] = 0.0
                    return token
        except Exception as exc:
            _log_swallow("9router login", exc)
        with _router_auth_lock:
            _router_auth["fail_at"] = time.monotonic()
        return None


def _router_usage(connection_id: str, cookie=None):
    """GET /api/usage/{id}. Prefers local CLI token; falls back to cookie."""
    token = _router_cli_token()
    headers = {"Accept": "application/json"}
    if token:
        headers["x-9r-cli-token"] = token
    elif cookie:
        headers["Cookie"] = cookie
    else:
        return None

    url = f"{_router_origin()}/api/usage/{quote(str(connection_id), safe='')}"
    for attempt in (0, 1):
        req = urllib.request.Request(url, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=QUOTA_TIMEOUT) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            if exc.code == 401 and attempt == 0 and not token:
                cookie = _router_login(force=True)
                if not cookie:
                    return None
                headers["Cookie"] = cookie
                continue
            return None
        except Exception as exc:
            _log_swallow("9router usage", exc)
            return None
    return None


def _read_router_connections() -> list:
    """Read-only snapshot of linked accounts from the 9router DB."""
    db_path = get_router_db_path()
    if not os.path.exists(db_path):
        return []
    try:
        with closing(sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=2.0)) as conn:
            rows = conn.execute(
                "SELECT id, provider, name, email, priority, isActive FROM providerConnections"
            ).fetchall()
    except Exception as exc:
        _log_swallow("9router connections", exc)
        return []
    return [
        {"id": r[0], "provider": r[1], "name": r[2], "email": r[3],
         "priority": r[4], "isActive": r[5]}
        for r in rows
    ]


def _quota_provider_skipped(provider: str) -> bool:
    """True when quota polling must skip this provider (see QUOTA_SKIP_PROVIDERS)."""
    prov = (provider or "").strip().lower()
    if not prov:
        return False
    base = prov.split("-chat-")[0] if prov.startswith("openai-compatible") else prov
    return prov in QUOTA_SKIP_PROVIDERS or base in QUOTA_SKIP_PROVIDERS



_AG_AVAILABLE_MODELS_URL = "https://daily-cloudcode-pa.googleapis.com/v1internal:fetchAvailableModels"
_AG_USER_AGENT = "antigravity/hub/2.24.0 darwin/arm64"


def _read_ag_conn_auth(connection_id: str) -> tuple[str, str]:
    """Read OAuth accessToken + projectId for one antigravity connection (read-only)."""
    db_path = get_router_db_path()
    if not connection_id or not os.path.exists(db_path):
        return "", ""
    try:
        with closing(sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=2.0)) as conn:
            row = conn.execute(
                "SELECT data FROM providerConnections WHERE id = ? AND provider = 'antigravity'",
                (connection_id,),
            ).fetchone()
    except Exception:
        return "", ""
    if not row or not row[0]:
        return "", ""
    try:
        raw = json.loads(row[0])
    except Exception:
        return "", ""
    psd = raw.get("providerSpecificData") if isinstance(raw.get("providerSpecificData"), dict) else {}
    tok = str(raw.get("accessToken") or psd.get("accessToken") or "").strip()
    proj = str(raw.get("projectId") or psd.get("projectId") or "").strip()
    return tok, proj


def _fetch_ag_available_models(token: str, project_id: str = "") -> dict | None:
    """Query Antigravity fetchAvailableModels (best-effort, short timeout)."""
    if not token:
        return None
    body = json.dumps({"project": project_id} if project_id else {}).encode("utf-8")
    req = urllib.request.Request(
        _AG_AVAILABLE_MODELS_URL,
        data=body,
        headers={
            "Authorization": f"Bearer {token}",
            "User-Agent": _AG_USER_AGENT,
            "Content-Type": "application/json",
            "X-Client-Name": "antigravity",
            "X-Client-Version": "2.24.0",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=4.0) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        models = data.get("models") if isinstance(data, dict) else None
        return models if isinstance(models, dict) else None
    except Exception as exc:
        _log_swallow("antigravity fetchAvailableModels", exc)
        return None


def _augment_antigravity_usage(conn: dict, usage):
    """Supplement 9router /api/usage with Carbon & Hydrogen (and missing Claude) from upstream."""
    if not isinstance(usage, dict):
        return usage
    quotas = usage.get("quotas")
    if not isinstance(quotas, dict) or not quotas:
        return usage
    tok, proj = _read_ag_conn_auth(str(conn.get("id") or ""))
    if not tok:
        return usage
    models = _fetch_ag_available_models(tok, proj)
    if not models:
        return usage

    merged = dict(quotas)
    has_claude = any(k.startswith("claude-") for k in merged)
    for mkey, mval in models.items():
        if not isinstance(mval, dict) or mval.get("isInternal"):
            continue
        is_special = mkey.startswith(("gemini-4-carbon", "gemini-4-hydrogen"))
        is_missing_claude = (not has_claude) and mkey.startswith("claude-")
        if not (is_special or is_missing_claude):
            continue
        if mkey in merged:
            continue
        disp = mval.get("displayName") or mkey
        if mkey.endswith("-disabled"):
            merged[mkey] = {"disabled": True, "displayName": disp}
            continue
        qi = mval.get("quotaInfo") if isinstance(mval.get("quotaInfo"), dict) else {}
        frac = qi.get("remainingFraction")
        if isinstance(frac, (int, float)) and not isinstance(frac, bool):
            pct = round(max(0.0, min(100.0, float(frac) * 100.0)), 1)
            rem_units = round(1000.0 * max(0.0, min(1.0, float(frac))))
            merged[mkey] = {
                "used": int(1000 - rem_units),
                "total": 1000,
                "remainingPercentage": pct,
                "resetAt": qi.get("resetTime"),
                "displayName": disp,
            }
    out = dict(usage)
    out["quotas"] = merged
    return out


def _quota_fetch_all(conns: list) -> list:
    """Fan out one /api/usage call per account, 8 at a time."""
    if not conns:
        return []
    conns = [c for c in conns if not _quota_provider_skipped(c.get("provider"))]
    if not conns:
        return []
    cookie = None if _router_cli_token() else _router_login()

    def one(conn):
        try:
            usage = _router_usage(conn["id"], cookie)
            if conn.get("provider") == "antigravity":
                usage = _augment_antigravity_usage(conn, usage)
            return _normalize_quota_account(conn, usage)
        except Exception as exc:
            _log_swallow("provider quota account", exc)
            return _normalize_quota_account(conn, None)

    with ThreadPoolExecutor(max_workers=QUOTA_MAX_WORKERS) as pool:
        return list(pool.map(one, conns))


def _quota_provider_rank(prov: str) -> int:
    base = prov.split("-chat-")[0] if prov.startswith("openai-compatible") else prov
    try:
        return QUOTA_PROVIDER_ORDER.index(base)
    except ValueError:
        return len(QUOTA_PROVIDER_ORDER)


def _quota_build() -> dict:
    conns = _read_router_connections()
    accounts = _quota_fetch_all(conns)

    grouped = {}
    for acct in accounts:
        grouped.setdefault(acct.get("provider") or "unknown", []).append(acct)

    def acct_sort(a):
        pcts = [g.get("pct") for g in a.get("groups") or [] if g.get("pct") is not None]
        if not pcts:
            pcts = [b.get("pct") for b in a.get("buckets") or [] if b.get("pct") is not None]
        return (min(pcts) if pcts else 999.0, a.get("priority") if a.get("priority") is not None else 999)

    providers = []
    for prov in sorted(grouped, key=lambda p: (_quota_provider_rank(p), p)):
        accts = sorted(grouped[prov], key=acct_sort)
        critical = sum(1 for a in accts if a.get("status") in ("exhausted", "auth_expired", "error"))
        providers.append({
            "provider": prov,
            "label": QUOTA_PROVIDER_LABELS.get(prov.split("-chat-")[0], prov),
            "accountCount": len(accts),
            "criticalCount": critical,
            "accounts": accts,
        })

    return {
        "ok": True,
        "fetchedAt": datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z"),
        "providers": providers,
    }


def _quota_filter(data: dict, provider_filter: str) -> dict:
    if not provider_filter:
        return data
    want = provider_filter.strip().lower()
    out = dict(data)
    out["providers"] = [
        p for p in data.get("providers") or []
        if (p.get("provider") or "").lower() == want
        or (p.get("label") or "").lower() == want
        or (p.get("provider") or "").lower().startswith(want + "-")
    ]
    return out


def _quota_load_disk():
    try:
        with open(QUOTA_CACHE_PATH, encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict) and data.get("ok") and data.get("providers"):
            return data
    except (OSError, ValueError):
        pass
    return None


def _quota_save_disk(data: dict) -> None:
    try:
        os.makedirs(os.path.dirname(QUOTA_CACHE_PATH), exist_ok=True)
        with _quota_disk_lock:
            fd, tmp = tempfile.mkstemp(dir=os.path.dirname(QUOTA_CACHE_PATH), suffix=".tmp")
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as fh:
                    json.dump(data, fh, separators=(",", ":"))
                os.replace(tmp, QUOTA_CACHE_PATH)
            except BaseException:
                with suppress(OSError):
                    os.unlink(tmp)
                raise
    except Exception as exc:
        _log_swallow("provider quota cache write", exc)


def _quota_kick_refresh() -> None:
    """Warm the cache in the background so a cold tab open still feels instant."""
    with _quota_lock:
        if _quota_refreshing["on"]:
            return
        _quota_refreshing["on"] = True

    def run():
        try:
            fresh = _quota_build()
            with _quota_lock:
                _quota_mem["data"] = fresh
                _quota_mem["at"] = time.monotonic()
            _quota_save_disk(fresh)
        except Exception as exc:
            _log_swallow("provider quota background refresh", exc)
        finally:
            with _quota_lock:
                _quota_refreshing["on"] = False

    threading.Thread(target=run, name="quota-refresh", daemon=True).start()


def get_provider_quota(refresh: bool = False, provider_filter: str = "") -> dict:
    """Cached quota snapshot. refresh=True forces a full fan-out fetch."""
    now = time.monotonic()
    with _quota_lock:
        data = _quota_mem["data"]
        age = now - _quota_mem["at"]

    if data is not None and not refresh:
        # Serve whatever we have immediately; only ?refresh=1 blocks on the
        # 41-account fan-out. A stale snapshot warms in the background.
        out = copy.deepcopy(data)
        out["cached"] = True
        if age >= QUOTA_TTL:
            out["stale"] = True
            _quota_kick_refresh()
        return _quota_filter(out, provider_filter)

    if data is None:
        disk = _quota_load_disk()
        if disk is not None:
            with _quota_lock:
                if _quota_mem["data"] is None:
                    _quota_mem["data"] = disk
                    _quota_mem["at"] = 0.0  # always stale: it is a restart leftover
            if not refresh:
                _quota_kick_refresh()
                out = copy.deepcopy(disk)
                out["cached"] = True
                out["stale"] = True
                return _quota_filter(out, provider_filter)

    try:
        fresh = _quota_build()
    except Exception as exc:
        _log_swallow("provider quota build", exc)
        if data is not None:
            out = copy.deepcopy(data)
            out["cached"] = True
            out["stale"] = True
            return _quota_filter(out, provider_filter)
        return {"ok": False, "error": "Gagal mengambil kuota dari 9router", "providers": []}

    with _quota_lock:
        _quota_mem["data"] = fresh
        _quota_mem["at"] = time.monotonic()
    _quota_save_disk(fresh)
    out = copy.deepcopy(fresh)
    out["cached"] = False
    return _quota_filter(out, provider_filter)


def build_fragments(sse_only: bool = False) -> dict:
    """Compute every dynamic HTML fragment (plus a couple of raw flags) in one
    place, so the initial full-page render and the /api/status poll can never
    drift apart. When sse_only=True, skip the 17 static blocks that SSE_CLIENT_KEYS
    never sends. Returns a JSON-serializable dict."""
    dash_active = is_dashboard_active()
    gw_active = service_active("hermes-gateway", user=True)
    router_up, router_ms, router_host = get_router_status()
    router_uptime = get_router_uptime() if router_up else ""
    model = get_current_model()
    ram_pct, ram_text = get_ram_info()
    ram_class = "down" if ram_pct >= 90 else ("warn" if ram_pct >= 75 else "up")
    cpu_temp, cpu_temp_text = get_cpu_temp()
    temp_class = "down" if cpu_temp >= 80 else ("warn" if cpu_temp >= 65 else "up")
    disk_text = get_disk_info()
    disk_pct = get_disk_pct()
    disk_class = "down" if disk_pct >= 95 else ("warn" if disk_pct >= 85 else "up")
    uptime_text = get_uptime()
    ts_ip, lan_ip = get_server_ips()
    internet_up, internet_ms, internet_target = get_internet_status()
    emmc_cls, emmc_text = get_emmc_health()
    zram_text = get_zram_info()
    gw_info = get_gateway_info()
    gw_summary_text, gw_summary_badge_class, cell_gw_platforms = get_gateway_platforms_summary()
    gateway_list_block = render_gateway_platforms_html()
    gateway_log_card = render_gateway_log_card()
    updating = _router_updating
    all_models = get_available_models_cached() if router_up else {}
    all_flat_models = [m for m_list in all_models.values() for m in m_list]
    model_not_listed = bool(all_flat_models) and model not in all_flat_models

    def cell(cls: str, text: str, title: str = "") -> str:
        t_attr = f' title="{html.escape(title)}"' if title else ""
        return f'<span class="value {cls}"{t_attr}><span class="dot {cls}"></span>{text}</span>'

    # Format providers info
    all_providers = get_all_configured_providers()
    prov_badges = []
    for p in all_providers:
        pname = html.escape(p["name"])
        ptype = p["type"]
        cls_name = "up" if ptype == "primary" else "warn"
        prov_badges.append(f'<span class="model-chip" style="font-size:.72rem;padding:.15rem .45rem"><span class="dot {cls_name}" style="width:5px;height:5px;margin-right:.3rem"></span>{pname}</span>')
    prov_html = " ".join(prov_badges) or '<span class="value">9router</span>'

    is_native_router = os.path.isfile("/etc/systemd/system/9router.service")
    router_sub_label = (
        f"native v{get_router_version()} · {get_router_image_date()}"
        if is_native_router else f"citra {get_router_image_date()}"
    )
    cells = {
        "dash": f'<span class="value" style="font-size:.72rem;color:var(--text-dim)">{html.escape(router_sub_label)}</span>' if router_up else '<span class="value down" style="font-size:.72rem">Offline</span>',
        "bot": cell("up" if gw_active else "down", "Aktif" if gw_active else "Mati"),
        "gw": f'<span class="value up">{gw_info}</span>' if gw_active else f'<span class="value down">{gw_info}</span>',
        "model": f'<span class="value {"warn" if model_not_listed else ""}" title="{"Model aktif tidak muncul di daftar model" if model_not_listed else ""}">{html.escape(model)}{" ⚠ tidak terdaftar" if model_not_listed else ""}</span>',
        "providers": f'<div style="display:flex;gap:.3rem;flex-wrap:wrap">{prov_html}</div>',
        "router": cell(
            "up" if router_up else "down",
            (f"Terhubung · {router_host} ({router_ms*1000:.0f}ms)"
             + (f" · aktif {router_uptime}" if router_uptime else "")
             if router_up else f"Tidak terhubung ({router_host})"),
        ),
        "ram": f'<span class="value {ram_class}">{ram_text}</span>',
        "zram": f'<span class="value">{zram_text}</span>',
        "temp": f'<span class="value {temp_class}">{cpu_temp_text}</span>',
        "emmc": f'<span class="value {emmc_cls}">{emmc_text}</span>',
        "disk": f'<span class="value {disk_class}">{disk_text}</span>',
        "uptime": f'<span class="value">{uptime_text}</span>',
        "lan": f'<span class="value">{lan_ip or "–"}</span>',
        "ts": f'<span class="value">{ts_ip or "–"}</span>',
        "internet": cell(
            "up" if internet_up else "down",
            f"Terhubung · {internet_target} ({internet_ms:.0f}ms)" if internet_up else f"Terputus ({internet_target})",
            title=f"Server tes: {internet_target} (DNS port 53, fallback: 8.8.8.8)",
        ),
        "gw_platforms": cell_gw_platforms,
    }

    update_result = get_router_update_result()
    if updating:
        log_card = render_log_card(tail_update_log(), update_result)
    else:
        log_card = render_log_card(tail_update_log(), update_result) if update_result.get("status") in ("success", "failed") else ""

    hermes_upd = get_hermes_update()
    hermes_behind = hermes_upd.get("behind", 0)
    hermes_local = hermes_upd.get("local", "?")
    hermes_status = hermes_upd.get("status", "unknown")
    hermes_result = get_hermes_update_result()
    hermes_log = html.escape(redact_sensitive_tokens(tail_hermes_update_log()))

    if hermes_result.get("running"):
        cells["hermes"] = f'<span class="value warn">Update berjalan…</span>'
    elif hermes_status == "available":
        cells["hermes"] = f'<span class="value warn">{html.escape(hermes_local)} (pembaruan tersedia)</span>'
    elif hermes_status == "ahead":
        cells["hermes"] = f'<span class="value up">{html.escape(hermes_local)} (lebih baru dari rilis)</span>'
    elif hermes_status == "current":
        cells["hermes"] = f'<span class="value up">{html.escape(hermes_local)} (terbaru)</span>'
    else:
        cells["hermes"] = f'<span class="value">{html.escape(hermes_local)}</span>'

    # Permanently render Hermes log card whenever log file exists or update result exists
    hermes_log_card = ""
    if hermes_log or hermes_result.get("status") != "idle" or os.path.exists("/root/.hermes/logs/update.log"):
        cls = "up" if hermes_result.get("status") == "success" else ("down" if hermes_result.get("status") == "failed" else "warn")
        summary_text = html.escape(hermes_result.get("summary", "")) if hermes_result.get("summary") else ("Pembaruan sedang berjalan…" if hermes_result.get("running") else "Log Terakhir Pembaruan Hermes")
        hermes_log_card = (
            f'<div id="hermes-log-card" style="margin-top:0.8rem">'
            f'<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:0.4rem">'
            f'<div class="update-hint {cls}" style="margin:0;flex:1">{summary_text}</div>'
            f'<button type="button" class="btn" style="width:auto;padding:0.2rem 0.6rem;font-size:0.72rem;margin:0" '
            f"onclick=\"safeStore('setItem','hermesLogDismissed','1');var c=document.getElementById('hermes-log-card');if(c)c.remove();if(window.syncLogUI)syncLogUI()\">"
            f'Sembunyikan Log</button>'
            f'</div>'
            f'<div class="logbox">{hermes_log or "(belum ada log)"}</div>'
            f'</div>'
        )

    cpu_pct = get_cpu_percent()
    _record_perf_sample(cpu_pct, ram_pct, cpu_temp)
    try:
        load1, load5, load15 = os.getloadavg()
        cell_load = f"{load1:.2f}, {load5:.2f}, {load15:.2f}"
    except Exception:
        cell_load = "?"

    if updating:
        update_block = '<div class="update-hint">{}</div>'.format(
            f'{ICON_CLOCK}Menjalankan pembaruan 9router di {html.escape(router_host)}…'
        )
    else:
        upd = get_update_status()
        cached_info = get_cached_router_info()
        installed_version = cached_info.get("version") or get_cached_router_version() or "?"
        latest_version = cached_info.get("latest_version") or ""
        npm_ahead = cached_info.get("npm_ahead", False)
        npm_latest = cached_info.get("npm_latest") or ""
        installed_label = html.escape(str(installed_version))
        latest_label = html.escape(str(latest_version))

        version_label = f"v{installed_label} &rarr; v{latest_label}" if (latest_version and latest_version != "?" and latest_version != installed_version) else f"v{installed_label}"
        cek_btn = (f'<a class="toggle restart" href="/check-update">'
                   f'{ICON_REFRESH}Cek Pembaruan 9router</a>')
        router_notes = get_9router_patch_notes()
        router_patch_notes_html = render_patch_notes_block("9router", router_notes)
        if upd == "available":
            update_block = (
                f'<a class="toggle" style="background:linear-gradient(135deg,var(--warning),#d9860bcc);'
                f'color:#141922" href="/update-router">'
                f'{ICON_ARROW_UP_CIRCLE}Pembaruan 9router tersedia ({version_label})</a>'
                + cek_btn
                + router_patch_notes_html
            )
        elif upd == "current":
            npm_note = ""
            if not is_native_router and npm_ahead and npm_latest and npm_latest != installed_version:
                npm_note = f' <span style="font-size:0.75rem;color:var(--text-dim)">(v{html.escape(str(npm_latest))} rilis di npm, menunggu build image Docker Hub)</span>'
            src_label = "npm" if is_native_router else "Docker Hub"
