# --- SSE (Server-Sent Events) infrastructure ---
_sse_clients: list = []  # list of (queue.Queue, threading.Event) tuples
_sse_clients_lock = threading.Lock()
_sse_active_event = threading.Event()

# --- Idle / deep-sleep bookkeeping -----------------------------------------
_conn_lock = threading.Lock()
_active_conns = 0
_last_activity = time.monotonic()
_socket_activated = False  # set in __main__ when systemd handed us the socket


def _touch_activity() -> None:
    global _last_activity
    _last_activity = time.monotonic()


def _conn_delta(n: int) -> None:
    global _active_conns
    with _conn_lock:
        _active_conns = max(0, _active_conns + n)


def _panel_idle_busy() -> bool:
    """True while a long-running job owns the process and must not be killed."""
    if _hermes_update_running or _hermes_check_running or _update_refreshing:
        return True
    if _models_bg_refreshing:
        return True
    if _quota_refreshing.get("on"):
        return True
    if (_clean_junk_result.get("status") or "") == "running":
        return True
    proc = _wa_pair_proc
    if proc is not None and proc.poll() is None:
        return True
    return False


def _trim_memory():
    """Run garbage collection and return free heap memory to the OS via malloc_trim."""
    try:
        gc.collect()
    except Exception:
        pass
    try:
        libc = ctypes.CDLL("libc.so.6")
        if hasattr(libc, "malloc_trim"):
            libc.malloc_trim(0)
    except Exception:
        try:
            c_lib = ctypes.util.find_library("c")
            if c_lib:
                libc = ctypes.CDLL(c_lib)
                if hasattr(libc, "malloc_trim"):
                    libc.malloc_trim(0)
        except Exception:
            pass


trim_memory = _trim_memory
# Keys SSE_SCRIPT's apply() actually reads. build_fragments() also renders static slots
# (model_chips alone is ~38 KB) that the page never replaces over SSE; sending them made every
# phone download and JSON.parse ~93 KB per second for nothing. /api/status still returns everything.
SSE_CLIENT_KEYS = (
    "cells", "cell_load", "cpu_pct", "ram_pct", "processes_table", "gateway_list_block",
    "gw_summary_text", "gw_summary_badge_class", "log_card", "hermes_log_card",
    "clean_junk_card", "gateway_log_card", "profiles_block", "update_block",
    "hermes_update_block",
)


def _sse_payload(frag: dict, delta: bool = False) -> str:
    """Serialize the client-visible subset of ``frag``.

    ``delta=True`` keeps only the keys whose serialized value changed since the
    previous delta push. Measured on the live panel: gateway_log_card is 18.3 KB
    and identical on 9/9 consecutive ticks, yet it was re-sent (and re-parsed,
    and re-diffed against innerHTML) every second because a RAM number moved.
    Per-key deltas cut ~22 KB/s per connected client on the STB.
    """
    if not delta:
        return json.dumps({k: frag[k] for k in SSE_CLIENT_KEYS if k in frag})
    out = {}
    now = time.monotonic()
    with _sse_last_keys_lock:
        for k in SSE_CLIENT_KEYS:
            if k not in frag:
                continue
            v = json.dumps(frag[k])
            last_entry = _sse_last_keys.get(k)
            if last_entry and last_entry[0] == v:
                # Update timestamp untuk mencegah cleanup
                _sse_last_keys[k] = (v, now)
                continue
            _sse_last_keys[k] = (v, now)
            out[k] = frag[k]
        # TTL cleanup: hapus entry yang tidak diupdate > TTL (memory leak prevention)
        stale_keys = [k for k, (_, ts) in _sse_last_keys.items() if now - ts > _SSE_LAST_KEYS_TTL]
        for k in stale_keys:
            del _sse_last_keys[k]
    return json.dumps(out)


_sse_last_data: str = ""  # last serialized fragments, for change detection
_sse_last_data_lock = threading.Lock()
_sse_last_keys: dict[str, tuple[str, float]] = {}  # per-key (last-sent serialization, timestamp), for delta pushes
_sse_last_keys_lock = threading.Lock()
_SSE_LAST_KEYS_TTL = 300.0  # 5 minutes TTL for unused keys

def _sse_push_loop():
    """Background worker thread:
    When clients are connected (user HAS the web page open and visible), compute
    fragments every 1s and push live updates immediately.
    When NO clients are connected, sleep deeply without CPU context-switch berkala."""
    global _sse_last_data
    last_state: dict = {}
    tick_count = 0
    while True:
        # Zero-Wakeup CPU: deep sleep without CPU context switch while no clients
        _sse_active_event.wait()

        with _sse_clients_lock:
            if not _sse_clients:
                _sse_active_event.clear()
                continue

        time.sleep(1)

        with _sse_clients_lock:
            if not _sse_clients:
                _sse_active_event.clear()
                continue

        tick_count += 1
        try:
            frag = build_fragments(sse_only=True)

            # Extract meaningful signals from cells for change detection
            cells = frag.get("cells", {})
            def _extract_status(cell_html: str) -> str:
                import re as _re
                for kw in ("Berjalan", "Berhenti", "Aktif", "Mati", "Terhubung", "Tidak terhubung", "Terputus"):
                    if kw in cell_html:
                        return kw
                m = _re.search(r'class="value(?:\s+[^\"]+)?"[^>]*>(.*?)</span>', cell_html)
                return m.group(1) if m else cell_html[:30]

            current_state = {
                "dash": _extract_status(cells.get("dash", "")),
                "bot": _extract_status(cells.get("bot", "")),
                "gw": _extract_status(cells.get("gw", "")),
                "model": _extract_status(cells.get("model", "")),
                "router": _extract_status(cells.get("router", "")),
                "internet": _extract_status(cells.get("internet", "")),
                "temp": cells.get("temp", ""),
                "disk": cells.get("disk", ""),
                "uptime": cells.get("uptime", ""),
                "lan": cells.get("lan", ""),
                "ts": cells.get("ts", ""),
                "model_chips": frag.get("model_chips", "")[:50],
                "rate_limit": bool(frag.get("rate_limit_card", "")),
                "update_block": frag.get("update_block", ""),
                "log_card": frag.get("log_card", ""),
                "hermes_update_block": frag.get("hermes_update_block", ""),
                "quick_links_block": frag.get("quick_links_block", ""),
                "dash_bot_btns_block": frag.get("dash_bot_btns_block", ""),
                "aux_tasks_block": frag.get("aux_tasks_block", "")[:100],
                "backup_models_block": frag.get("backup_models_block", "")[:100],
                "processes_table": frag.get("processes_table", "")[:80],
                "updating": frag.get("updating", False),
                "gateway_list_block": frag.get("gateway_list_block", "")[:100],
                "profiles_block": frag.get("profiles_block", "")[:100],
                "gw_summary_text": frag.get("gw_summary_text", ""),
                "gw_summary_badge_class": frag.get("gw_summary_badge_class", ""),
                "hermes_log_card": frag.get("hermes_log_card", ""),
                "clean_junk_card": frag.get("clean_junk_card", ""),
                "gateway_log_card": frag.get("gateway_log_card", ""),
            }

            should_push = current_state != last_state or frag.get("updating", False)
            # Periodic sync every 10s to keep metrics strictly live
            if tick_count >= 10:
                should_push = True
                tick_count = 0

            if not should_push:
                continue

            last_state = current_state
            # Per-key delta: a tick where only cpu_pct moved must not drag the
            # 18 KB gateway log block (and the 8.5 KB process table) along.
            data = _sse_payload(frag, delta=True)
            if data == "{}":
                continue
            with _sse_last_data_lock:
                _sse_last_data = data

            needs_trim = False
            with _sse_clients_lock:
                dead = []
                for q, evt in _sse_clients:
                    try:
                        q.put_nowait(data)
                    except queue.Full:
                        dead.append((q, evt))
                    except Exception:
                        dead.append((q, evt))
                for d in dead:
                    try:
                        d[1].set()
                        _sse_clients.remove(d)
                    except (ValueError, Exception):
                        pass
                if not _sse_clients and dead:
                    _sse_active_event.clear()
                    needs_trim = True

            if needs_trim:
                _trim_memory()
        except Exception as e:
            sys.stderr.write(f"[panel] SSE push loop error: {e}\n")
            continue

# Start SSE push thread
threading.Thread(target=_sse_push_loop, daemon=True).start()


